  insert into public.missions (slug, mission_no, emoji, title, description, category_id, difficulty, status, stages, reward_rules, engine_options, objectives, access, level_id, risk_level, family, cover_image_path)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content)
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points, media)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 0, $j${"emoji":"🏘️","title":{"ha":"Wanene ke da wannan matsala?","en":"Who has this problem?"},"lines":[{"text":{"ha":"Iyali da ba su da firji: kayan lambu suna lalacewa a cikin zafi.","en":"A family with no fridge: vegetables spoil in the heat."}},{"text":{"ha":"Makaranta ko asibiti da ba su da famfo: mutane ba sa wanke hannu da kyau.","en":"A school or clinic with no tap: people cannot wash their hands properly."}},{"text":{"ha":"Mai lambu da ruwa kaɗan: shuke-shuke suna bushewa.","en":"A gardener with little water: plants dry out."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 1, $j${"emoji":"🧱","title":{"ha":"Kayan aiki da halayensu","en":"Materials and their properties"},"lines":[{"text":{"ha":"Yumɓu yana da ƙananan ramuka, ruwa yana iya ratsawa ta cikinsa. Filastik ba ya barin ruwa ya ratsa.","en":"Clay has tiny pores, so water can pass through it. Plastic does not let water through."}},{"text":{"ha":"Yashi yana riƙe ruwa. Kwalbar filastik tana da sauƙi, tana riƙe ruwa, kuma ana samunta a ko’ina.","en":"Sand holds water. A plastic bottle is light, holds water and is easy to find."}},{"text":{"ha":"Ko da yaushe ka tambayi: me ya sa aka zaɓi wannan kayan? Menene iyakarsa?","en":"Always ask: why was this material chosen? What is its limit?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 2, $j${"emoji":"❄️","title":{"ha":"Kimiyya: na’urar sanyaya","en":"Science: the cooler"},"lines":[{"text":{"ha":"Idan ruwa yana ƙafewa, yana ɗaukar zafi daga abin da ke kewaye da shi. Don haka cikin na’urar yana yin sanyi.","en":"When water evaporates it takes heat from what is around it. So the inside of the cooler gets cooler."}},{"text":{"ha":"Zafi, bushewar iska da iska mai motsi suna sa ƙafewa ya yi sauri. A rana mai ɗanshi, ƙafewa yana jinkiri.","en":"Heat, dry air and moving air make evaporation faster. On a humid day, evaporation is slower."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 3, $j${"emoji":"🧼","title":{"ha":"Kimiyya: wurin wanke hannu","en":"Science: the hand-washing station"},"lines":[{"text":{"ha":"Sabulu da gogewa suna cire datti da ƙwayoyin cuta daga fata, ruwa mai gudana kuma yana kwashe su.","en":"Soap and rubbing lift dirt and germs off the skin, and running water carries them away."}},{"text":{"ha":"Feda da ƙafa tana nufin ba ka taɓa famfo ko hannun da hannu mai datti ba.","en":"A foot pedal means you do not touch a tap or handle with dirty hands."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 4, $j${"emoji":"💧","title":{"ha":"Kimiyya: ban ruwa da kwalba","en":"Science: bottle drip watering"},"lines":[{"text":{"ha":"Ƙaramin rami yana barin ruwa ya fita a hankali. Dole iska ta shiga kwalbar domin ruwa ya fita.","en":"A tiny hole lets water out slowly. Air has to get into the bottle for the water to come out."}},{"text":{"ha":"Ruwa yana sauka kusa da tushen shuka, a hankali.","en":"The water drips slowly, close to the plant’s roots."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 5, $j${"emoji":"🛠️","title":{"ha":"Me zai iya lalacewa?","en":"What can go wrong?"},"lines":[{"text":{"ha":"Na’urar sanyaya: yashi ya bushe, a rana, ko rana mai ɗanshi.","en":"Cooler: the sand dries out, it stands in the sun, or the day is humid."}},{"text":{"ha":"Wurin wanke hannu: ruwa maras tsabta ko sabulu ya ƙare.","en":"Hand-washing station: dirty water or no soap left."}},{"text":{"ha":"Ban ruwa: ramin ya yi yawa ko ya toshe.","en":"Drip bottle: the hole is too big or blocked."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 6, $j${"emoji":"📏","title":{"ha":"Gwaji mai adalci da aunawa","en":"Fair testing and measuring"},"lines":[{"text":{"ha":"Canza abu ɗaya kawai a lokaci guda, sauran su zama iri ɗaya.","en":"Change only one thing at a time and keep the rest the same."}},{"text":{"ha":"Ka rubuta karatunka a tebur, ka kwatanta, sannan ka yanke shawara.","en":"Write your readings in a table, compare them, then decide."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, v_n - 1 + 7, $j${"emoji":"🧾","title":{"ha":"Nawa ne kuɗin ginawa?","en":"How much will it cost?"},"lines":[{"text":{"ha":"Ka jera kayan aiki, ka rubuta farashin kasuwar yankinka, ka haɗa su waje ɗaya.","en":"List the materials, write your local market price for each, and add them up."}},{"text":{"ha":"Wannan shi ne kuɗin raka’a. Sai ka ƙara farashin sayarwa don ganin riba.","en":"That is the unit cost. Then add a selling price to see the profit."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'predict', v_c + 0, $j${"type":"predict","kind":"predict","key":"predict","ask":{"ha":"Wace na’urar sanyaya ce za ta fi sanyi a rana mai zafi da bushewa? (Dukansu suna da rigar da aka jiƙa a saman.)","en":"Which cooler will stay coolest on a hot, dry day? (All three have a damp cloth on top.)"},"options":[{"ha":"Yashi mai ɗanshi, a inuwa","en":"Wet sand, in the shade"},{"ha":"Yashi busasshe, a rana","en":"Dry sand, in the sun"},{"ha":"Yashi mai ɗanshi, a rana","en":"Wet sand, in the sun"}],"correct":0,"table":[{"label":{"ha":"Zafin waje","en":"Outside air"},"value":"34 °C"},{"label":{"ha":"Yashi mai ɗanshi, inuwa","en":"Wet sand, shade"},"value":"24 °C"},{"label":{"ha":"Yashi mai ɗanshi, rana","en":"Wet sand, sun"},"value":"26 °C"},{"label":{"ha":"Yashi busasshe, rana","en":"Dry sand, sun"},"value":"34 °C"}],"explain":{"ha":"Yashi mai ɗanshi yana da ruwan da zai ƙafe, don haka yana ɗaukar zafi. Inuwa tana rage zafin da ke shigowa.","en":"Wet sand has water that can evaporate, so it takes heat away. Shade reduces the heat coming in."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'test', v_c + 1, $j${"type":"sim","kind":"sim","key":"test","title":{"ha":"Gwada na’urar sanyaya","en":"Test the cooler"},"intro":{"ha":"Canza saiti, ka yi gwaji, ka rubuta karatu.","en":"Change the settings, run a test and record the reading."},"goal":{"ha":"Ka nemo saitin da ya fi sanyaya cikin na’urar.","en":"Find the setting that keeps the inside coolest."},"unit":"°C","base":34,"better":"low","minRuns":3,"vars":[{"key":"place","label":{"ha":"Ina aka ajiye na’urar?","en":"Where is the cooler?"},"options":[{"id":"shade","label":{"ha":"A inuwa","en":"In the shade"},"effect":0},{"id":"sun","label":{"ha":"A rana","en":"In the sun"},"effect":2}]},{"key":"sand","label":{"ha":"Yashi","en":"The sand"},"options":[{"id":"wet","label":{"ha":"Mai ɗanshi","en":"Wet"},"effect":-8},{"id":"dry","label":{"ha":"Busasshe","en":"Dry"},"effect":0}]},{"key":"cloth","label":{"ha":"Rigar saman na’ura","en":"Cloth on top"},"options":[{"id":"damp","label":{"ha":"Rigar da aka jiƙa","en":"Damp cloth"},"effect":-2},{"id":"none","label":{"ha":"Babu riga","en":"No cloth"},"effect":0}]}],"explain":{"ha":"Saitin mafi sanyi shi ne inuwa, yashi mai ɗanshi da rigar da aka jiƙa. Kowanne yana taimaka wa ƙafewa ko rage zafi.","en":"The coolest setting is shade, wet sand and a damp cloth. Each one helps evaporation or reduces heat."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'compare', v_c + 2, $j${"type":"sort","key":"compare","items":[{"emoji":"🏺","kind":"good","name":{"ha":"Tukunyar yumɓu","en":"Clay pot"},"why":{"ha":"Yumɓu yana da ƙananan ramuka, ruwa yana ratsawa.","en":"Clay has tiny pores so water can pass through."}},{"emoji":"🪣","kind":"poor","name":{"ha":"Bokitin filastik","en":"Plastic bucket"},"why":{"ha":"Filastik ba ya barin ruwa ya ratsa, don haka ƙafewa a waje ya yi ƙaranci.","en":"Plastic does not let water through, so there is little evaporation outside."}},{"emoji":"🥣","kind":"poor","name":{"ha":"Kwanon ƙarfe","en":"Metal bowl"},"why":{"ha":"Ƙarfe ba shi da ƙananan ramuka.","en":"Metal has no pores."}},{"emoji":"🏖️","kind":"good","name":{"ha":"Yashi mai ɗanshi tsakanin tukwane","en":"Wet sand between the pots"},"why":{"ha":"Yana riƙe ruwa wanda zai ƙafe a hankali.","en":"It holds water that evaporates slowly."}}],"ask":{"ha":"Zaɓi mai kyau ne ga na’urar sanyaya?","en":"Is it a good choice for the cooler?"},"options":[{"kind":"good","icon":"✅","label":{"ha":"Zaɓi mai kyau","en":"Good choice"}},{"kind":"poor","icon":"❌","label":{"ha":"Ba shi da kyau","en":"Poor choice"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'faults', v_c + 3, $j${"type":"sort","key":"faults","items":[{"emoji":"🏜️","kind":"likely","name":{"ha":"Yashi ya bushe","en":"The sand dried out"},"why":{"ha":"Ba ruwan da zai ƙafe, don haka babu sanyaya.","en":"No water left to evaporate, so no cooling."}},{"emoji":"☀️","kind":"likely","name":{"ha":"An ajiye ta a rana kai tsaye","en":"It stands in direct sun"},"why":{"ha":"Rana tana ƙara zafi.","en":"The sun adds heat."}},{"emoji":"🌫️","kind":"likely","name":{"ha":"Rana mai ɗanshi sosai","en":"A very humid day"},"why":{"ha":"Iska mai ɗanshi tana rage ƙafewa.","en":"Humid air slows evaporation."}},{"emoji":"🎨","kind":"unlikely","name":{"ha":"Launin rigar shuɗi ne","en":"The cloth is blue"},"why":{"ha":"Launin riga ba shi da muhimmanci a nan.","en":"The colour of the cloth does not matter here."}},{"emoji":"🏷️","kind":"unlikely","name":{"ha":"An rubuta suna a kan tukunya","en":"A name is written on the pot"},"why":{"ha":"Rubutu ba ya shafar ƙafewa.","en":"Writing does not affect evaporation."}}],"ask":{"ha":"Shin wannan zai iya sa na’urar ta kasa sanyaya?","en":"Could this make the cooler fail?"},"options":[{"kind":"likely","icon":"⚠️","label":{"ha":"Eh, zai iya","en":"Yes, likely"}},{"kind":"unlikely","icon":"✅","label":{"ha":"A’a, bai shafa ba","en":"No, unlikely"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'plan', v_c + 4, $j${"type":"business_plus","kind":"business_plus","key":"plan"}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'present', v_c + 5, $j${"type":"reflect","kind":"reflect","key":"present","title":{"ha":"Gabatar da ra’ayinka","en":"Present your idea"},"prompts":[{"ha":"Wace na’ura daga cikin uku ce za ta fi taimaka wa al’ummarka, kuma me ya sa?","en":"Which of the three devices would help your community most, and why?"},{"ha":"Rubuta abubuwa uku da za su iya sa ta lalace, da gyara ɗaya.","en":"Write three things that could make it fail, and one improvement."},{"ha":"Nawa za ta ci, kuma wa zai saye ta?","en":"What would it cost, and who would buy it?"}],"minChars":15}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, v_q + 0, $j${"ha":"Me ya sa yashi mai ɗanshi yake sanyaya cikin na’urar?","en":"Why does the wet sand cool the inside of the cooler?"}$j$::jsonb, $j$[{"ha":"Ruwan da ke ƙafewa yana ɗaukar zafi","en":"Water evaporating takes heat away"},{"ha":"Yashi yana da sanyi ta halitta","en":"Sand is cold by nature"},{"ha":"Tukunya tana yin sanyi da kanta","en":"The pot makes cold by itself"}]$j$::jsonb, 0, $j${"ha":"Ƙafewar ruwa yana ɗaukar zafi daga kewaye.","en":"Evaporation takes heat from the surroundings."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, v_q + 1, $j${"ha":"Me ya sa ake amfani da yumɓu ba filastik ba?","en":"Why is clay used rather than plastic?"}$j$::jsonb, $j$[{"ha":"Yumɓu yana da ƙananan ramuka da ruwa ke ratsawa","en":"Clay has tiny pores that water passes through"},{"ha":"Yumɓu ya fi nauyi","en":"Clay is heavier"},{"ha":"Yumɓu ja ne","en":"Clay is red"}]$j$::jsonb, 0, $j${"ha":"Ruwa yana ratsa yumɓu kuma yana ƙafewa a waje.","en":"Water passes through clay and evaporates outside."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, v_q + 2, $j${"ha":"A wace rana ce na’urar sanyaya za ta fi rashin aiki?","en":"On which day will the cooler work least well?"}$j$::jsonb, $j$[{"ha":"Rana mai zafi da ɗanshi","en":"A hot, humid day"},{"ha":"Rana mai zafi da bushewa","en":"A hot, dry day"},{"ha":"Rana mai iska da bushewa","en":"A windy, dry day"}]$j$::jsonb, 0, $j${"ha":"Iska mai ɗanshi tana rage ƙafewa.","en":"Humid air slows evaporation."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, v_q + 3, $j${"ha":"Me ya sa kwalbar ban ruwa take digowa a hankali?","en":"Why does the drip bottle drip slowly?"}$j$::jsonb, $j$[{"ha":"Ramin ƙarami ne","en":"The hole is tiny"},{"ha":"Kwalbar shuɗi ce","en":"The bottle is blue"},{"ha":"Ruwan yana da sanyi","en":"The water is cold"}]$j$::jsonb, 0, $j${"ha":"Ƙaramin rami yana barin ruwa ya fita a hankali.","en":"A tiny hole lets water out slowly."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, v_q + 4, $j${"ha":"Me ya sa feda ta ƙafa take da amfani a wurin wanke hannu?","en":"Why is a foot pedal useful at a hand-washing station?"}$j$::jsonb, $j$[{"ha":"Ba ka taɓa famfo da hannu mai datti ba","en":"You do not touch the tap with dirty hands"},{"ha":"Tana sa ruwa yayi sanyi","en":"It makes the water cold"},{"ha":"Tana yin ƙara","en":"It makes a noise"}]$j$::jsonb, 0, $j${"ha":"Ba ka sake dasa datti a kan famfo ba.","en":"You do not put dirt back on the tap."}$j$::jsonb, 5);
  insert into public.missions (slug, mission_no, emoji, title, description, category_id, difficulty, status, stages, reward_rules, engine_options, objectives, access, level_id, risk_level, family)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"📦","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Baba yana da tarin tsohuwar takarda da akwatuna. Za a jefar da su?","en":"Baba has a pile of old paper and boxes. Should they be thrown away?"}},{"text":{"ha":"A’a! Za mu koyi yadda za su zama abubuwa masu amfani.","en":"No! We will learn how they can become useful things."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"📄","title":{"ha":"Menene takarda da kwali?","en":"What are paper and cardboard?"},"lines":[{"text":{"ha":"An yi takarda ne da ƙananan zaren tsirrai (fibres).","en":"Paper is made of tiny plant fibres."}},{"text":{"ha":"Kwali ya fi takarda kauri, wani lokaci yana da yadudduka da yawa.","en":"Cardboard is thicker than paper and often has several layers."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🛠️","title":{"ha":"Abubuwan da za mu iya yi","en":"Things we can make"},"lines":[{"text":{"ha":"Sabuwar takarda daga tsohuwa, mai riƙe fensir, akwatin ajiya, tukunyar iri, da mai tsara kayan rubutu.","en":"New paper from old paper, a pencil holder, a storage box, a seedling pot and a desk organiser."}},{"text":{"ha":"Muna amfani da abin da muke da shi, ba ma jefar da shi.","en":"We use what we already have instead of throwing it away."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🌍","title":{"ha":"Me ya sa sake amfani yake da amfani?","en":"Why is reuse useful?"},"lines":[{"text":{"ha":"Sake amfani yana rage shara.","en":"Reusing cuts down waste."}},{"text":{"ha":"Wani zai iya yin abubuwa daga tsohuwar takarda ya sayar.","en":"Someone could make things from old paper and sell them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Manya ne kawai ke amfani da wuƙa, abin yanka mai kaifi, ko wuta. Kada ka ƙona takarda.","en":"Only adults use knives, sharp cutters or fire. Never burn paper."}},{"text":{"ha":"Kada ka yi amfani da takardar da ta ɗauki mai, abinci mai maiko, magani ko sinadari. Takarda mai ɗanshi tana yin gyambo, don haka a busar da ita. Ka wanke hannunka.","en":"Do not use paper that held grease, medicine or chemicals. Damp paper can grow mould, so dry it well. Wash your hands."}},{"text":{"ha":"Wannan wasa ne kawai.","en":"This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ptear', 0, $j${"emoji":"📄","name":{"ha":"Yaga takarda","en":"Tear the paper"},"text":{"ha":"Yaga tsohuwar takarda zuwa ƙananan guntuka.","en":"Tear old clean paper into small pieces."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'psoak', 1, $j${"emoji":"💧","name":{"ha":"Jiƙa a ruwa","en":"Soak in water"},"text":{"ha":"Sa guntukan a cikin kwano da ruwa mai tsabta, ka bar su na wani lokaci.","en":"Put the pieces in a bowl of clean water and leave them for a while."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pmash', 2, $j${"emoji":"🥣","name":{"ha":"Dunƙule da hannu","en":"Mash with your hands"},"text":{"ha":"Ka matse ka dunƙule takardar da ta jiƙe har ta zama kamar kwaɓa.","en":"Squeeze and mash the soaked paper until it is like soft mush."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pspread', 3, $j${"emoji":"🧺","name":{"ha":"Shimfiɗa a kan raga","en":"Spread on a screen"},"text":{"ha":"Shimfiɗa kwaɓar a kan raga mai tsabta ko yadi, siriri.","en":"Spread the mush thinly on a clean screen or cloth."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ppress', 4, $j${"emoji":"🫳","name":{"ha":"Matse ruwa","en":"Press out the water"},"text":{"ha":"Ka matse a hankali don ruwa ya fita.","en":"Press gently so the water comes out."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pdry', 5, $j${"emoji":"☀️","name":{"ha":"Busar da shi sosai","en":"Dry it completely"},"text":{"ha":"Ka bar shi ya bushe sosai a inuwa mai iska. Takarda mai ɗanshi tana iya yin gyambo.","en":"Let it dry completely in an airy place. Damp paper can grow mould."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ptube', 6, $j${"emoji":"✂️","name":{"ha":"Yanka ɗan tsiri","en":"Cut a strip"},"text":{"ha":"Babba ne ke yanka takarda da almakashi.","en":"An adult cuts the paper strip with scissors."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'proll', 7, $j${"emoji":"🥫","name":{"ha":"Naɗa a kan gwangwani","en":"Roll around a can"},"text":{"ha":"Ka naɗa tsiri a kan gwangwani mara komai da santsi.","en":"Roll the strip around a smooth empty can."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pfold', 8, $j${"emoji":"🪺","name":{"ha":"Nade ƙasa","en":"Fold the bottom"},"text":{"ha":"Ka nade ƙasan tukunyar takardar ka matse.","en":"Fold the bottom of the paper pot and press it flat."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'psoil', 9, $j${"emoji":"🌱","name":{"ha":"Saka ƙasa da iri","en":"Add soil and a seed"},"text":{"ha":"Ka saka ƙasa da iri, ka zuba ruwa kaɗan. Ka wanke hannunka bayan haka.","en":"Add soil and a seed, and water a little. Wash your hands afterwards."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'recycle', 0, $j${"id":"recycle","emoji":"♻️","name":{"ha":"Yin sabuwar takarda","en":"Making recycled paper"},"steps":["ptear","psoak","pmash","pspread","ppress","pdry"],"summary":{"ha":"Yaga, jiƙa, dunƙule, shimfiɗa, matse, busar.","en":"Tear, soak, mash, spread, press, dry."},"result":{"emoji":"📄","name":{"ha":"Sabuwar takarda","en":"Recycled paper"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'pot', 1, $j${"id":"pot","emoji":"🌱","name":{"ha":"Tukunyar iri ta takarda","en":"Paper seedling pot"},"steps":["ptube","proll","pfold","psoil"],"summary":{"ha":"Yanka (babba), naɗa, nade, saka ƙasa.","en":"Cut (adult), roll, fold, add soil."},"result":{"emoji":"🌱","name":{"ha":"Tukunyar iri","en":"A seedling pot"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'reuse', 0, $j${"type":"sort","key":"reuse","items":[{"emoji":"📦","kind":"yes","name":{"ha":"Akwatin kwali mai tsabta","en":"A clean cardboard box"},"why":{"ha":"Za a iya sake amfani da shi.","en":"It can be reused."}},{"emoji":"📓","kind":"yes","name":{"ha":"Tsohon littafin rubutu","en":"An old notebook"},"why":{"ha":"Takarda ce mai tsabta.","en":"It is clean paper."}},{"emoji":"📰","kind":"yes","name":{"ha":"Jarida","en":"Newspaper"},"why":{"ha":"Ana amfani da ita wajen tukunyar iri.","en":"It works for seedling pots."}},{"emoji":"🍕","kind":"no","name":{"ha":"Akwatin da ya ɗauki abinci mai maiko","en":"A box with greasy food on it"},"why":{"ha":"Maiko da abinci ba su da kyau a sake amfani.","en":"Grease and food scraps are not good for reuse."}},{"emoji":"🦠","kind":"no","name":{"ha":"Takarda mai gyambo","en":"Mouldy paper"},"why":{"ha":"Gyambo yana da haɗari. Ka jefar.","en":"Mould is harmful. Throw it away."}}],"ask":{"ha":"Za a iya sake amfani da shi?","en":"Can we reuse it?"},"options":[{"kind":"yes","icon":"♻️","label":{"ha":"Eh, za a iya","en":"Yes, reuse it"}},{"kind":"no","icon":"🚫","label":{"ha":"A’a","en":"No"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"📄","kind":"safe","name":{"ha":"Yaga takarda","en":"Tearing paper"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"💧","kind":"safe","name":{"ha":"Matse takarda da ta jiƙe","en":"Squeezing soaked paper"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka da wuƙa ko abin yanka mai kaifi","en":"Cutting with a knife or sharp cutter"},"why":{"ha":"Mai kaifi yana yanka hannu. Babba ne kawai.","en":"Sharp tools cut skin. Only an adult."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Ƙona takarda","en":"Burning paper"},"why":{"ha":"Wuta tana ƙonewa. Babba ne kawai, kuma ba mu ƙona ba.","en":"Fire burns. We never burn paper in this lesson."}},{"emoji":"🧪","kind":"adult","name":{"ha":"Amfani da takardar da ta ɗauki sinadari","en":"Using paper that held chemicals"},"why":{"ha":"Kada ka taɓa ta. Ka gaya wa babba.","en":"Do not touch it. Tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'holder', 2, $j${"type":"sort","key":"holder","items":[{"emoji":"📜","kind":"yes","name":{"ha":"Bututun kwali","en":"A cardboard tube"},"why":{"ha":"Yana tsaye kuma yana riƙe fensir.","en":"It stands up and holds pencils."}},{"emoji":"🥣","kind":"yes","name":{"ha":"Akwatin hatsi mara komai da tsabta","en":"A clean empty cereal box"},"why":{"ha":"Ana iya yanka shi da taimakon babba.","en":"An adult can help cut it."}},{"emoji":"📔","kind":"yes","name":{"ha":"Murfin tsohon littafi","en":"An old notebook cover"},"why":{"ha":"Yana da ƙarfi kaɗan.","en":"It is a little stiff."}},{"emoji":"🪟","kind":"no","name":{"ha":"Gilashi mai tsage","en":"Broken glass"},"why":{"ha":"Mai haɗari. Kada ka taɓa.","en":"Dangerous. Do not touch it."}},{"emoji":"🫧","kind":"no","name":{"ha":"Takarda mai ɗanshi ƙwarai","en":"Very wet paper"},"why":{"ha":"Ba ta riƙe siffa kuma tana iya yin gyambo.","en":"It will not hold its shape and can grow mould."}}],"ask":{"ha":"Za a iya yin mai riƙe fensir da shi?","en":"Can we make a pencil holder with it?"},"options":[{"kind":"yes","icon":"✏️","label":{"ha":"Eh","en":"Yes"}},{"kind":"no","icon":"❌","label":{"ha":"A’a","en":"No"}}]}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Daga me ake yin takarda?","en":"What is paper made from?"}$j$::jsonb, $j$[{"ha":"Ƙananan zaren tsirrai","en":"Tiny plant fibres"},{"ha":"Yashi","en":"Sand"},{"ha":"Ƙarfe","en":"Metal"}]$j$::jsonb, 0, $j${"ha":"An yi takarda daga zaren tsirrai (fibres).","en":"Paper is made of plant fibres."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Menene mataki na farko na yin sabuwar takarda?","en":"What is the first step in making recycled paper?"}$j$::jsonb, $j$[{"ha":"Yaga takarda","en":"Tear the paper"},{"ha":"Ƙona takarda","en":"Burn the paper"},{"ha":"Fenti","en":"Paint it"}]$j$::jsonb, 0, $j${"ha":"Muna farawa da yaga takarda.","en":"We start by tearing the paper."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya kamata ka yi wa sabuwar takarda kafin amfani?","en":"What must you do to new paper before using it?"}$j$::jsonb, $j$[{"ha":"Busar da ita sosai","en":"Dry it completely"},{"ha":"Barin ta ta jiƙe","en":"Leave it wet"},{"ha":"Ƙona ta","en":"Burn it"}]$j$::jsonb, 0, $j${"ha":"Takarda mai ɗanshi tana iya yin gyambo.","en":"Damp paper can grow mould."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wa ke yanka da abin yanka mai kaifi?","en":"Who uses a sharp cutter?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Abin yanka mai kaifi yana cutarwa. Babba ne kawai.","en":"Sharp cutters can hurt. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Za mu ƙona takarda a wannan darasi?","en":"Do we burn paper in this lesson?"}$j$::jsonb, $j$[{"ha":"A’a, ba mu ƙonawa","en":"No, never"},{"ha":"Eh","en":"Yes"},{"ha":"Wani lokaci","en":"Sometimes"}]$j$::jsonb, 0, $j${"ha":"Wuta tana da haɗari, ba ma ƙona takarda.","en":"Fire is dangerous. We never burn paper."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya sa sake amfani da takarda yake da kyau?","en":"Why is reusing paper good?"}$j$::jsonb, $j$[{"ha":"Yana rage shara","en":"It cuts down waste"},{"ha":"Yana ƙara shara","en":"It makes more waste"},{"ha":"Babu amfani","en":"It has no use"}]$j$::jsonb, 0, $j${"ha":"Sake amfani yana rage shara.","en":"Reusing reduces waste."}$j$::jsonb, 5);
  insert into public.missions (slug, mission_no, emoji, title, description, category_id, difficulty, status, stages, reward_rules, engine_options, objectives, access, level_id, risk_level, family)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🗑️","title":{"ha":"Takardar da ake jefarwa","en":"The paper we throw away"},"lines":[{"text":{"ha":"A makaranta da gida, ana jefar da takarda da kwali da yawa.","en":"At school and at home, a lot of paper and cardboard is thrown away."}},{"text":{"ha":"Za mu koyi dalilin da ya sa za a iya sake amfani da su, da yadda ake tsara abu mai amfani daga gare su.","en":"We will learn why they can be reused, and how to design something useful from them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🧵","title":{"ha":"Kayan aiki da halayensu","en":"Materials and their properties"},"lines":[{"text":{"ha":"Takarda an yi ta da ƙananan zaren tsirrai. Tana shan ruwa, kuma tana yin rauni idan ta jiƙe.","en":"Paper is made of tiny plant fibres. It absorbs water and gets weaker when wet."}},{"text":{"ha":"Kwali yana da yadudduka. Kwali mai raƙuman ruwa (corrugated) yana da layi mai lanƙwasa tsakanin lebur biyu.","en":"Cardboard has layers. Corrugated cardboard has a wavy layer between two flat ones."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🔬","title":{"ha":"Kimiyya: yadda sabuwar takarda ke samuwa","en":"Science: how recycled paper forms"},"lines":[{"text":{"ha":"A cikin ruwa, zaren takarda suna rabuwa da juna.","en":"In water, the paper fibres separate from each other."}},{"text":{"ha":"Idan aka shimfiɗa aka matse, ruwan yana fita, zaren suna haɗuwa da juna su manne, takarda kuma ta sake zama zane mai ƙarfi.","en":"When the mixture is spread and pressed, the water leaves, the fibres tangle and stick together, and a sheet forms again."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🔬","title":{"ha":"Kimiyya: siffa tana ƙara ƙarfi","en":"Science: shape adds strength"},"lines":[{"text":{"ha":"Takarda ɗaya lebur tana lankwasuwa da sauƙi. Idan ka naɗa ta zuwa bututu ko ka nade ta, tana riƙe nauyi sosai.","en":"A single flat sheet bends easily. Rolled into a tube or folded, it holds much more weight."}},{"text":{"ha":"Kwali mai raƙuman ruwa yana da ƙarfi saboda siffar layinsa mai lanƙwasa.","en":"Corrugated cardboard is strong because of the shape of its wavy layer."}},{"text":{"ha":"Siffa tana ƙara ƙarfi ba tare da ƙarin kayan aiki ba.","en":"Shape adds strength without adding more material."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"📏","title":{"ha":"Aunawa da tsara","en":"Measure and plan"},"lines":[{"text":{"ha":"Ka auna da rula, ka zana tsari a takarda tukuna, ka yi alama kafin yanka.","en":"Measure with a ruler, draw a plan on paper first and mark before cutting."}},{"text":{"ha":"Yanka da kaifi na babba ne ko ana yi da taimakonsa.","en":"Cutting with a sharp tool is for an adult, or done with one helping."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🧾","title":{"ha":"Kuɗi da ƙima","en":"Cost and value"},"lines":[{"text":{"ha":"Takarda da kwali da aka sake amfani da su kusan kyauta ne, amma manne, lokaci da kayan aiki suna da farashi.","en":"Reused paper and cardboard cost almost nothing, but glue, time and tools do have a cost."}},{"text":{"ha":"Ka lissafa kuɗin raka’a, ka saita farashi, ka duba riba.","en":"Work out the unit cost, set a price and check the profit."}},{"text":{"ha":"Lambobin da ke wannan darasi misali ne. Yi amfani da farashin kasuwarka.","en":"Numbers in this lesson are examples. Use your own market prices."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Wuƙa, abin yanka mai kaifi da wuta na manya ne. Babba ne ke cire ƙusoshin ƙarfe (staples).","en":"Knives, sharp cutters and fire are for adults. An adult removes staples."}},{"text":{"ha":"Kada ka yi amfani da takardar da ta ɗauki maiko, magani ko sinadari. Takarda mai ɗanshi tana yin gyambo: ka busar da ita, ka yi amfani da ita da wuri.","en":"Do not use paper that held grease, medicine or chemicals. Wet paper grows mould: dry it and use it soon."}},{"text":{"ha":"Wannan wasa ne kawai.","en":"This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ptear', 0, $j${"emoji":"📄","name":{"ha":"Yaga takarda","en":"Tear the paper"},"text":{"ha":"Yaga tsohuwar takarda zuwa ƙananan guntuka.","en":"Tear old clean paper into small pieces."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'psoak', 1, $j${"emoji":"💧","name":{"ha":"Jiƙa a ruwa","en":"Soak in water"},"text":{"ha":"Sa guntukan a cikin kwano da ruwa mai tsabta, ka bar su na wani lokaci.","en":"Put the pieces in a bowl of clean water and leave them for a while."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pmash', 2, $j${"emoji":"🥣","name":{"ha":"Dunƙule da hannu","en":"Mash with your hands"},"text":{"ha":"Ka matse ka dunƙule takardar da ta jiƙe har ta zama kamar kwaɓa.","en":"Squeeze and mash the soaked paper until it is like soft mush."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pspread', 3, $j${"emoji":"🧺","name":{"ha":"Shimfiɗa a kan raga","en":"Spread on a screen"},"text":{"ha":"Shimfiɗa kwaɓar a kan raga mai tsabta ko yadi, siriri.","en":"Spread the mush thinly on a clean screen or cloth."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ppress', 4, $j${"emoji":"🫳","name":{"ha":"Matse ruwa","en":"Press out the water"},"text":{"ha":"Ka matse a hankali don ruwa ya fita.","en":"Press gently so the water comes out."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pdry', 5, $j${"emoji":"☀️","name":{"ha":"Busar da shi sosai","en":"Dry it completely"},"text":{"ha":"Ka bar shi ya bushe sosai a inuwa mai iska. Takarda mai ɗanshi tana iya yin gyambo.","en":"Let it dry completely in an airy place. Damp paper can grow mould."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'ptube', 6, $j${"emoji":"✂️","name":{"ha":"Yanka ɗan tsiri","en":"Cut a strip"},"text":{"ha":"Babba ne ke yanka takarda da almakashi.","en":"An adult cuts the paper strip with scissors."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'proll', 7, $j${"emoji":"🥫","name":{"ha":"Naɗa a kan gwangwani","en":"Roll around a can"},"text":{"ha":"Ka naɗa tsiri a kan gwangwani mara komai da santsi.","en":"Roll the strip around a smooth empty can."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pfold', 8, $j${"emoji":"🪺","name":{"ha":"Nade ƙasa","en":"Fold the bottom"},"text":{"ha":"Ka nade ƙasan tukunyar takardar ka matse.","en":"Fold the bottom of the paper pot and press it flat."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'psoil', 9, $j${"emoji":"🌱","name":{"ha":"Saka ƙasa da iri","en":"Add soil and a seed"},"text":{"ha":"Ka saka ƙasa da iri, ka zuba ruwa kaɗan. Ka wanke hannunka bayan haka.","en":"Add soil and a seed, and water a little. Wash your hands afterwards."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'recycle', 0, $j${"id":"recycle","emoji":"♻️","name":{"ha":"Yin sabuwar takarda","en":"Making recycled paper"},"steps":["ptear","psoak","pmash","pspread","ppress","pdry"],"summary":{"ha":"Yaga, jiƙa, dunƙule, shimfiɗa, matse, busar.","en":"Tear, soak, mash, spread, press, dry."},"result":{"emoji":"📄","name":{"ha":"Sabuwar takarda","en":"Recycled paper"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'pot', 1, $j${"id":"pot","emoji":"🌱","name":{"ha":"Tukunyar iri ta takarda","en":"Paper seedling pot"},"steps":["ptube","proll","pfold","psoil"],"summary":{"ha":"Yanka (babba), naɗa, nade, saka ƙasa.","en":"Cut (adult), roll, fold, add soil."},"result":{"emoji":"🌱","name":{"ha":"Tukunyar iri","en":"A seedling pot"}}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'predict', 0, $j${"type":"predict","kind":"predict","key":"predict","ask":{"ha":"Takarda iri ɗaya: wace siffa ce za ta riƙe littattafai mafi yawa a saman ta?","en":"The same paper: which shape will hold the most books on top?"},"options":[{"ha":"Lebur","en":"Flat sheet"},{"ha":"Naɗaɗɗe zuwa bututu","en":"Rolled into a tube"},{"ha":"Nade sau ɗaya","en":"Folded once"}],"correct":1,"table":[{"label":{"ha":"Lebur","en":"Flat sheet"},"value":"1 littafi / book"},{"label":{"ha":"Nade sau ɗaya","en":"Folded once"},"value":"3 littattafai / books"},{"label":{"ha":"Bututu","en":"Tube"},"value":"7 littattafai / books"}],"explain":{"ha":"Bututu yana raba nauyi a kewaye kuma yana da wuyar lankwasuwa. Wannan samfuri ne, ba ma’auni na gaske ba.","en":"A tube spreads the load around and is hard to bend. This is a model, not a real measurement."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'strength', 1, $j${"type":"sim","kind":"sim","key":"strength","title":{"ha":"Gina ginshiƙin takarda","en":"Build a paper column"},"intro":{"ha":"Zaɓi siffa da yadudduka, ka ga littattafai nawa zai riƙe a samfurin.","en":"Choose a shape and layers and see how many books it holds in the model."},"goal":{"ha":"Ka nemo ginshiƙi mafi ƙarfi.","en":"Find the strongest column."},"unit":"books","base":1,"better":"high","minRuns":3,"vars":[{"key":"shape","label":{"ha":"Siffa","en":"Shape"},"options":[{"id":"flat","label":{"ha":"Lebur","en":"Flat"},"effect":0},{"id":"fold","label":{"ha":"Nade","en":"Folded"},"effect":2},{"id":"tube","label":{"ha":"Bututu","en":"Tube"},"effect":6}]},{"key":"layers","label":{"ha":"Yadudduka","en":"Layers"},"options":[{"id":"one","label":{"ha":"Ɗaya","en":"One"},"effect":0},{"id":"two","label":{"ha":"Biyu","en":"Two"},"effect":2}]}],"explain":{"ha":"Bututu mai yadudduka biyu ya fi ƙarfi: siffa da ƙarin yadudduka suna ƙara ƙarfi.","en":"A tube with two layers is strongest: shape and extra layers both add strength."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'choice', 2, $j${"type":"sort","key":"choice","items":[{"emoji":"📜","kind":"good","name":{"ha":"Bututun kwali mai kauri","en":"A thick cardboard tube"},"why":{"ha":"Yana da ƙarfi kuma yana tsaye.","en":"It is strong and stands up."}},{"emoji":"📰","kind":"poor","name":{"ha":"Jarida mai sirara kaɗai","en":"Thin newspaper alone"},"why":{"ha":"Tana lankwasuwa kuma ba ta riƙe siffa.","en":"It bends and does not hold its shape."}},{"emoji":"🍕","kind":"poor","name":{"ha":"Akwatin da ya ɗauki abinci mai maiko","en":"A greasy food box"},"why":{"ha":"Ba shi da tsabta don riƙe abubuwa.","en":"It is not hygienic."}},{"emoji":"📦","kind":"good","name":{"ha":"Kwali mai raƙuman ruwa","en":"Corrugated cardboard"},"why":{"ha":"Layinsa mai lanƙwasa yana ba shi ƙarfi.","en":"Its wavy layer gives it strength."}}],"ask":{"ha":"Zaɓi mai kyau ne don mai riƙe fensir?","en":"Is it a good choice for a pencil holder?"},"options":[{"kind":"good","icon":"✅","label":{"ha":"Zaɓi mai kyau","en":"Good choice"}},{"kind":"poor","icon":"❌","label":{"ha":"Ba shi da kyau","en":"Poor choice"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 3, $j${"type":"safety","key":"safety","items":[{"emoji":"📏","kind":"safe","name":{"ha":"Aunawa da zana tsari","en":"Measuring and drawing a plan"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"💧","kind":"safe","name":{"ha":"Jiƙa da dunƙule takarda","en":"Soaking and mashing paper"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka kwali mai kauri da abin yanka mai kaifi","en":"Cutting thick cardboard with a sharp cutter"},"why":{"ha":"Mai kaifi yana yanka hannu. Babba ne kawai.","en":"Sharp tools cut skin. Only an adult."}},{"emoji":"📎","kind":"adult","name":{"ha":"Cire ƙusoshin ƙarfe (staples)","en":"Removing staples"},"why":{"ha":"Suna da kaifi. Babba ne kawai.","en":"They are sharp. Only an adult."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Ƙona takarda","en":"Burning paper"},"why":{"ha":"Wuta tana ƙonewa. Ba ma ƙona takarda.","en":"Fire burns. We never burn paper."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'plan', 4, $j${"type":"business_plus","kind":"business_plus","key":"plan"}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'simulation', 'present', 5, $j${"type":"reflect","kind":"reflect","key":"present","title":{"ha":"Gabatar da mai riƙe fensirinka","en":"Present your pencil holder"},"prompts":[{"ha":"Wace matsala ce mai riƙe fensirinka yake warwarewa, kuma wa yake buƙatarsa?","en":"What problem does your pencil holder solve, and who needs it?"},{"ha":"Wane kayan aiki ka yi amfani da su, kuma me ya sa ka zaɓe su?","en":"Which materials did you use, and why did you choose them?"},{"ha":"Me za ka gyara a ƙirar ta biyu?","en":"What would you improve in a second version?"}],"minChars":15}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ke faruwa da zaren takarda a cikin ruwa?","en":"What happens to paper fibres in water?"}$j$::jsonb, $j$[{"ha":"Suna rabuwa da juna","en":"They separate from each other"},{"ha":"Suna narkewa gaba ɗaya","en":"They dissolve completely"},{"ha":"Suna zama ƙarfe","en":"They turn to metal"}]$j$::jsonb, 0, $j${"ha":"Zaren suna rabuwa, daga baya su sake haɗuwa idan aka busar.","en":"The fibres separate and then tangle together again when dried."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ya sa takarda mai ɗanshi take rauni?","en":"Why is wet paper weak?"}$j$::jsonb, $j$[{"ha":"Zaren suna rabuwa da juna a cikin ruwa","en":"The fibres separate from each other in water"},{"ha":"Tana yin nauyi sosai","en":"It becomes very heavy"},{"ha":"Tana yin ja","en":"It turns red"}]$j$::jsonb, 0, $j${"ha":"Ruwa yana raunana haɗin zaren.","en":"Water weakens the hold between the fibres."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa kwali mai raƙuman ruwa yake da ƙarfi?","en":"Why is corrugated cardboard strong?"}$j$::jsonb, $j$[{"ha":"Layinsa mai lanƙwasa yana ƙara ƙarfi","en":"Its wavy layer adds strength"},{"ha":"Yana da launi","en":"It has a colour"},{"ha":"Yana da nauyi sosai","en":"It is very heavy"}]$j$::jsonb, 0, $j${"ha":"Siffar lanƙwasa tana ƙara ƙarfi.","en":"The wavy shape adds strength."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wace siffa ce ta fi riƙe nauyi a samfurinmu?","en":"Which shape held the most weight in our model?"}$j$::jsonb, $j$[{"ha":"Bututu","en":"A tube"},{"ha":"Lebur","en":"A flat sheet"},{"ha":"Duka iri ɗaya","en":"All the same"}]$j$::jsonb, 0, $j${"ha":"Bututu yana raba nauyi.","en":"A tube spreads the load."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Kuɗin raka’a ₦300, farashi ₦500, an sayar da 10, babu kuɗin sau ɗaya. Menene riba?","en":"Unit cost ₦300, price ₦500, 10 sold, no one-off cost. What is the profit?"}$j$::jsonb, $j$[{"ha":"₦2,000","en":"₦2,000"},{"ha":"₦5,000","en":"₦5,000"},{"ha":"₦200","en":"₦200"}]$j$::jsonb, 0, $j${"ha":"Kuɗin shiga 5,000 − kuɗin da aka kashe 3,000 = ₦2,000.","en":"Revenue 5,000 − cost 3,000 = ₦2,000."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya kamata ka yi wa sabuwar takarda mai ɗanshi?","en":"What should you do with damp recycled paper?"}$j$::jsonb, $j$[{"ha":"Busar da ita sosai ka yi amfani da ita da wuri","en":"Dry it well and use it soon"},{"ha":"Ɓoye ta a jaka mai ɗumi","en":"Hide it in a warm bag"},{"ha":"Ƙona ta","en":"Burn it"}]$j$::jsonb, 0, $j${"ha":"Takarda mai ɗanshi tana yin gyambo.","en":"Damp paper grows mould."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Wa ke cire ƙusoshin ƙarfe (staples) daga takarda?","en":"Who removes staples from paper?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Suna da kaifi. Babba ne kawai.","en":"They are sharp. Only an adult."}$j$::jsonb, 5);
