begin
  if exists (select 1 from public.missions where slug = 'paper-l1') then raise notice 'mission paper-l1 already exists - skipping'; return; end if;
  values ('paper-l1', (select coalesce(max(mission_no), 0) + 1 from public.missions), '📄', $j${"ha":"TSOHUWAR TAKARDA TA SAMI SABUWAR RAYUWA","en":"OLD PAPER GETS A NEW LIFE"}$j$::jsonb, $j${"ha":"Ka koyi yadda tsohuwar takarda da kwali za su zama abubuwa masu amfani.","en":"Learn how old paper and cardboard become useful things."}$j$::jsonb,
          (select id from public.categories where slug = 'environment'), 'beginner', 'draft', $j$["teach","show","practice","challenge","quiz","reward"]$j$::jsonb, $j${"teach":[10,"Resource Explorer"],"show":5,"practice":[10,"Young Inventor"],"reuse":5,"safety":5,"holder":5,"quiz":5,"finish":[10,"Home Inventor"]}$j$::jsonb, $j${"header_title":{"ha":"TSOHUWAR TAKARDA TA SAMI SABUWAR RAYUWA","en":"OLD PAPER GETS A NEW LIFE"},"mixed":true}$j$::jsonb, $j$[{"ha":"Ka iya faɗar abubuwan takarda da kwali da za a iya sake amfani da su.","en":"You can name paper and cardboard things we can reuse."},{"ha":"Ka san matakan yin takarda ta sake amfani: yaga, jiƙa, dunƙule, shimfiɗa, busar.","en":"You know the steps of making recycled paper: tear, soak, mash, spread, dry."},{"ha":"Ka san ayyukan da manya kaɗai ke yi, kamar yanka da kaifi.","en":"You know the jobs only adults do, like sharp cutting."}]$j$::jsonb,
